from fractions import Fraction as F
import json
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
names='TUVW'
cost=dict(zip(names,map(F,['1.8','1.5','1.2','0.8'])))
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def stop(s):
 w=sum(rows[i][1] for i in s)
 return min((sum(F(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])],w) for i in s),'ABCD'[a]) for a in range(4))
def buy(s,t,remaining):
 w=sum(rows[i][1] for i in s)
 total=cost[t]
 for v in (0,1):
  b=tuple(i for i in s if rows[i][2][names.index(t)]==v)
  if b: total+=F(sum(rows[i][1] for i in b),w)*best(b,remaining)[0]
 return total
def best(s,available):
 options=[stop(s)]
 for t in available: options.append((buy(s,t,tuple(x for x in available if x!=t) if len(available)==1 else ()),t))
 return min(options)
# Explicit two-test horizon at root; best receives second-test candidates and buy terminates.
s=tuple(range(8))
values={'STOP':stop(s)[0]}
for t in names:
 values[t]=buy(s,t,tuple(x for x in names if x!=t))
first=min(values,key=values.get)
next_actions={}
for v in (0,1):
 b=tuple(i for i in s if rows[i][2][names.index(first)]==v)
 next_actions[str(v)]=best(b,tuple(t for t in names if t!=first))[1] if b else 'IMPOSSIBLE'
print(json.dumps({'first':first,'first_losses':{k:float(v) for k,v in values.items()},'next':next_actions}))
print('exact',values)
for v in (0,1):
 b=tuple(i for i in s if rows[i][2][names.index(first)]==v)
 print('branch',v,'stop',stop(b),'test_options',[(t,buy(b,t,())) for t in names if t!=first])

