from fractions import Fraction as F
import json
# W=1 retains rows A drift, B drift, D drift; repeated stored reading adds no evidence.
modes='ABCD'
rows=[('A',3,{'T':0,'U':0,'V':0}),('B',5,{'T':0,'U':0,'V':1}),('D',5,{'T':0,'U':0,'V':1})]
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
cost={'T':F('1.8'),'U':F('1.5'),'V':F('7.2')}
def repairs(rs):
 w=sum(r[1] for r in rs)
 return {a:sum(F(r[1]*loss[i][modes.index(r[0])],w) for r in rs) for i,a in enumerate(modes)}
def best(rs):
 d=repairs(rs)
 a=min(d,key=d.get)
 return d[a],a
values=repairs(rows)
for t,c in cost.items():
 values[t]=c
 for v in (0,1):
  b=[r for r in rows if r[2][t]==v]
  if b: values[t]+=F(sum(r[1] for r in b),13)*best(b)[0]
a=min(values,key=values.get)
result={'posterior':{m:float(F(sum(r[1] for r in rows if r[0]==m),13)) for m in modes},'remaining_losses':{k:float(v) for k,v in values.items()},'action':a,'repair_after':{}}
if a in cost:
 for v in (0,1):
  b=[r for r in rows if r[2][a]==v]
  result['repair_after'][str(v)]=best(b)[1] if b else 'IMPOSSIBLE'
# Direct checks: repair B= (3*22+5*8)/13; V=7.2+(5*8)/13.
assert values['B']==F(106,13)
assert values['V']==F(36,5)+F(40,13)
print(json.dumps(result))

